class TenantConfigAllowRecoverPassAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isAllowRecoverPass returns null on a freshly created holder.
     */
    public function testAllowRecoverPassNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigAllowRecoverPassAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isAllowRecoverPassAssigned());
        $this->assertNull($holder->isAllowRecoverPass());
    }
}
